package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/url"
	"strconv"
	"strings"

	"google.golang.org/protobuf/types/known/structpb"

	metadatav1 "github.com/mellifera/mellifera/proto/mellifera/metadata/v1"
)

// errNoCandidates marks an empty (but valid) upstream result list — a soft
// error the core records without corrupting the document.
var errNoCandidates = errors.New("shikimori returned no candidates")

// Convert normalizes the raw shikimori payload into the RU-first
// sources.shikimori namespace: title{romaji,russian}, kind, status, episodes,
// aired_on, description, genres, score, url, poster. The payload is either a
// single anime object (the by-id fetch) or a list (the search); a list runs
// the preference score and picks ONE candidate. The resolved shikimori_id
// rides inside the metadata under resolved_ids (the core lifts it into
// doc.identifiers; Merge strips it). Provenance carries hints only — the core
// stamps _provenance authoritatively. On an anchored run the plan's episodes
// extra (extras[1]) additionally decodes into per-episode EpisodeTitle
// entries (episode-titles) outside the run namespace. A non-run (empty list,
// unparsable body) sets Error and leaves metadata empty; Convert never errors
// the chain.
func (*sourceImpl) Convert(_ context.Context, req *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	entry, err := decodeEntry(req.GetRawResponse(), req.GetQuery())
	if err != nil {
		return &metadatav1.ConvertResult{
			Error: &metadatav1.Error{Code: errorCode(err), Message: err.Error()},
		}, nil
	}
	m := namespaceFields(entry)
	m[resolvedIDsKey] = map[string]any{idKey: int64(entry.ID)}
	// The request plan's extras are aligned by position (proto D4) and this
	// plugin declares two: extras[0] the roles fetch (the convention cast,
	// source.go BuildRequest), extras[1] the episodes fetch (episode-titles).
	// An unfetched extra (soft-failed) or an unusable body simply leaves its
	// contribution absent — honest absence, never an empty entry.
	if extras := req.GetExtraResponses(); len(extras) > 0 && extras[0].GetFetched() {
		if cast := castField(extras[0].GetBody()); len(cast) > 0 {
			m[castKey] = cast
		}
	}
	// The episodes leg contributes ONLY the per-episode EpisodeTitle entries
	// (episode-titles D2): the series namespace mapping above — the title
	// object, cast, provenance hints — is untouched by it. Search plans
	// declare no extras, so a search payload produces no entries.
	var episodeTitles []*metadatav1.EpisodeTitle
	if extras := req.GetExtraResponses(); len(extras) > 1 && extras[1].GetFetched() {
		episodeTitles = episodeTitleEntries(extras[1].GetBody())
	}
	sourceURL, _ := m["url"].(string)
	meta := toStruct(m)
	return &metadatav1.ConvertResult{
		Metadata:      meta,
		Provenance:    provenanceHints(meta, sourceURL),
		EpisodeTitles: episodeTitles,
	}, nil
}

// animeEntry mirrors the shikimori anime payload (v1 API). score is a decimal
// STRING upstream; json.Number accepts both the string and a bare number.
type animeEntry struct {
	ID       int         `json:"id"`
	Name     string      `json:"name"`
	Russian  string      `json:"russian"`
	Kind     string      `json:"kind"`
	Status   string      `json:"status"`
	Score    json.Number `json:"score"`
	Episodes int         `json:"episodes"`
	AiredOn  string      `json:"aired_on"`

	// Carried only by the search-list payload (identify-match-override);
	// pointer so an absent upstream year stays absent in the candidate.
	Year *int32 `json:"year"`

	Description string       `json:"description"`
	URL         string       `json:"url"`
	Image       animeImage   `json:"image"`
	Genres      []animeGenre `json:"genre"`
}

type animeImage struct {
	Original string `json:"original"`
}

type animeGenre struct {
	Name    string `json:"name"`
	Russian string `json:"russian"`
}

// decodeEntry parses the raw response body: a list runs selectCandidate over
// the query, a single object is the by-id fetch answer, anything else is a
// parse error.
func decodeEntry(body []byte, query *structpb.Struct) (animeEntry, error) {
	var list []animeEntry
	if err := json.Unmarshal(body, &list); err == nil {
		if len(list) == 0 {
			return animeEntry{}, errNoCandidates
		}
		return selectCandidate(list, query), nil
	}
	var single animeEntry
	if err := json.Unmarshal(body, &single); err != nil {
		return animeEntry{}, fmt.Errorf("shikimori response is neither a list nor an anime object: %w", err)
	}
	return single, nil
}

// errorCode maps decodeEntry failures onto the Convert error vocabulary.
func errorCode(err error) string {
	if errors.Is(err, errNoCandidates) {
		return "upstream_empty"
	}
	return "parse_error"
}

// selectCandidate picks the best candidate deterministically: the preference
// score (below), ties broken by upstream order (strictly-greater keeps the
// first). A candidate agreeing on nothing still scores 0 and stays selectable
// — the selection is non-erroring when nothing agrees.
func selectCandidate(list []animeEntry, query *structpb.Struct) animeEntry {
	best := list[0]
	bestScore := candidateScore(best, query)
	for _, cand := range list[1:] {
		if s := candidateScore(cand, query); s > bestScore {
			best, bestScore = cand, s
		}
	}
	return best
}

// candidateScore prefers year + movie/series kind + episode-count agreement
// (each worth 2). Absent query facts score nothing; no fact ever penalizes.
func candidateScore(c animeEntry, query *structpb.Struct) int {
	f := query.GetFields()
	score := 0
	if q := int64(f[yearKey].GetNumberValue()); q > 0 && airedYear(c.AiredOn) == q {
		score += 2
	}
	if q := f[kindKey].GetStringValue(); q != "" && (q == kindMovie) == (c.Kind == kindMovie) {
		score += 2
	}
	if q := int64(f[episodesKey].GetNumberValue()); q > 0 && int64(c.Episodes) == q {
		score += 2
	}
	return score
}

// airedYear reads the "YYYY" prefix of an aired_on date ("1998-04-03"); an
// unparsable or empty date yields 0 and never matches a query year.
func airedYear(airedOn string) int64 {
	if len(airedOn) < 4 {
		return 0
	}
	y, err := strconv.ParseInt(airedOn[:4], 10, 64)
	if err != nil {
		return 0
	}
	return y
}

// namespaceFields builds the sources.shikimori namespace map (RU-first):
// genres prefer the Russian genre names, relative upstream paths become
// absolute against the API base. A poster whose absolute URL is a known
// missing-art asset writes NO poster key at all (artwork, write-side drop):
// upstream-placeholder = upstream not providing the field, the honest-absence
// convention.
func namespaceFields(e animeEntry) map[string]any {
	m := map[string]any{
		"title":       map[string]any{"romaji": e.Name, "russian": e.Russian},
		"kind":        e.Kind,
		"status":      e.Status,
		"episodes":    int64(e.Episodes),
		"aired_on":    e.AiredOn,
		"description": e.Description,
		"genres":      genreNames(e.Genres),
		"url":         absoluteURL(e.URL),
	}
	if poster := absoluteURL(e.Image.Original); !missingArtURL(poster) {
		m["poster"] = poster
	}
	if s, err := e.Score.Float64(); err == nil && s > 0 {
		m["score"] = s
	}
	return m
}

// missingArtPrefix is the shikimori missing-art asset path prefix (artwork):
// any URL under it is the upstream's "no art" placeholder, never real data.
const missingArtPrefix = "/assets/globals/missing"

// missingArtURL reports whether u's PATH carries the known missing-art asset
// prefix — the prefix rule, not an exact-URL list. Callers run absoluteURL
// first, so the check sees the absolute path whether the payload carried a
// relative API path or an absolute URL. The predicate is deliberately
// duplicated across the plugin boundary (design D9) and pinned by the
// committed golden fixture internal/api/testdata/golden/missing_art.json,
// which the core walk-side test consumes too — one side drifting alone
// fails its own suite.
func missingArtURL(u string) bool {
	parsed, err := url.Parse(u)
	if err != nil {
		return false
	}
	return strings.HasPrefix(parsed.Path, missingArtPrefix)
}

// genreNames renders genres RU-first (russian name, falling back to the
// original).
func genreNames(genres []animeGenre) []any {
	out := make([]any, 0, len(genres))
	for _, g := range genres {
		out = append(out, displayFirst(g.Russian, g.Name))
	}
	return out
}

// rolesEntry mirrors one entry of the shikimori roles payload
// (GET /api/animes/{id}/roles, v1): a character with its voice-actor
// credits ("seyu" is the upstream's own spelling of the field).
type rolesEntry struct {
	Name    string       `json:"name"`
	Russian string       `json:"russian"`
	Image   animeImage   `json:"image"`
	Seiyuu  []roleSeiyuu `json:"seyu"`
}

// roleSeiyuu mirrors one voice-actor credit inside a roles entry.
type roleSeiyuu struct {
	Name    string `json:"name"`
	Russian string `json:"russian"`
}

// castField composes the media-data convention cast array (design D1) from a
// roles payload: one entry per character — name the character (russian
// preferred), role the free-text seiyuu credit when the character has one,
// photo_url the character portrait (made absolute like the poster). An
// entry without a usable character name is skipped; a body that is not a
// roles array, or one with no usable entries, composes nothing (nil) so the
// cast field stays ABSENT rather than empty.
func castField(body []byte) []any {
	var roles []rolesEntry
	if err := json.Unmarshal(body, &roles); err != nil {
		return nil
	}
	out := make([]any, 0, len(roles))
	for _, r := range roles {
		name := displayFirst(r.Russian, r.Name)
		if name == "" {
			continue
		}
		entry := map[string]any{"name": name}
		if credit := seiyuuCredit(r.Seiyuu); credit != "" {
			entry["role"] = credit
		}
		// A known missing-art portrait path is upstream not providing the
		// photo (artwork write-side drop): the entry stays, the field is
		// honestly absent.
		if portrait := absoluteURL(r.Image.Original); portrait != "" && !missingArtURL(portrait) {
			entry["photo_url"] = portrait
		}
		out = append(out, entry)
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// seiyuuCredit renders the free-text seiyuu credit (russian names preferred,
// comma-joined when a character has several); no credit renders empty.
func seiyuuCredit(seyu []roleSeiyuu) string {
	names := make([]string, 0, len(seyu))
	for _, s := range seyu {
		if n := displayFirst(s.Russian, s.Name); n != "" {
			names = append(names, n)
		}
	}
	return strings.Join(names, ", ")
}

// episodesEntry mirrors one entry of the shikimori episodes payload
// (GET /api/animes/{id}/episodes, v1): the episode number — numbered within
// the matched season, shikimori anime ids being per-season entries — and the
// names the upstream serves for it. The `russian` name is preferred
// (RU-first, design D4); `name` is the other served name and the fallback.
// The upstream's description field is deliberately NOT decoded: it serves
// none for episodes, and this source contributes the convention title ONLY.
type episodesEntry struct {
	Episode int    `json:"episode"`
	Name    string `json:"name"`
	Russian string `json:"russian"`
}

// episodeTitleEntries decodes an episodes payload into the per-episode
// EpisodeTitle contributions (episode-titles D2): one entry per usable
// payload entry — episode the served episode number, metadata exactly
// {"title": the russian name when the entry serves one, else the other
// served name} — NEVER a description. Entries without a usable name are
// skipped, an unparsable body decodes to nil: honest absence — no empty
// entries, no placeholders, the payload's own order preserved.
func episodeTitleEntries(body []byte) []*metadatav1.EpisodeTitle {
	var entries []episodesEntry
	if err := json.Unmarshal(body, &entries); err != nil {
		return nil
	}
	out := make([]*metadatav1.EpisodeTitle, 0, len(entries))
	for _, e := range entries {
		title := displayFirst(e.Russian, e.Name)
		if title == "" {
			continue
		}
		out = append(out, &metadatav1.EpisodeTitle{
			Episode:  int64(e.Episode),
			Metadata: toStruct(map[string]any{"title": title}),
		})
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// displayFirst prefers the first non-empty string (the RU-first idiom the
// namespace already uses for titles and genres).
func displayFirst(a, b string) string {
	if a != "" {
		return a
	}
	return b
}
